/* Single source of truth for the expanded product catalog and its images. */
const SHOP_COMMON_EXTRAS = [
  ["Pot Terracotta 15cm","Pot",18000,"🪴"],["Pot Terracotta 25cm","Pot",32000,"🪴"],["Polybag Besar 40x40","Pot",22000,"🪴"],
  ["Media Tanah Organik 10kg","Media Tanam",28000,"🌿"],["Cocopeat 5kg","Media Tanam",24000,"🥥"],["Sekam Bakar 5kg","Media Tanam",18000,"🌾"],
  ["Kompos Kascing 2kg","Pupuk",22000,"♻️"],["Pupuk NPK Buah 1kg","Pupuk",35000,"🧪"],["Pupuk Daun Organik 500ml","Pupuk",24000,"🧪"],
  ["Sekop Tangan Stainless","Tools",28000,"🪓"],["Sarung Tangan Kebun","Tools",18000,"🧤"],["Sprayer Tekan 5L","Tools",65000,"💦"],
  ["Label Tanaman 20pcs","Tools",12000,"🏷️"],["Tray Semai 128 Lubang","Tools",26000,"🧊"],["pH Meter Tanah Digital","Tools",85000,"📏"],
  ["Kit Hidroponik Wick 12 Lubang","Hydroponics",95000,"💧"]
];

const shopSlug=value => value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
PLANTS.forEach((plant,index)=>{
  const seedCategory=["Hias","Pohon buah"].includes(plant.kategori) ? "Bibit" : "Benih";
  const seedLabel=seedCategory==="Bibit" ? "Bibit" : "Benih";
  const seedName=`${seedLabel} ${plant.nama}`; const finalSeedName=PRODUCTS.some(product=>product.nama===seedName)?`${seedName} Nusantara`:seedName; PRODUCTS.push({id:shopSlug(finalSeedName),nama:finalSeedName,kategori:seedCategory,harga:seedCategory==="Bibit"?18000+(index%5)*7000:9000+(index%6)*3000,rating:4.4+(index%6)/10,ulas:40+(index%9)*18,badge:index%7===0?"Beginner Pick":index%11===0?"Popular":"",emoji:plant.emoji,related:plant.id,stok:30+(index%8)*10});
  const bundleName=`Paket Media & Nutrisi ${plant.nama}`; const finalBundleName=PRODUCTS.some(product=>product.nama===bundleName)?`${bundleName} Nusantara`:bundleName; PRODUCTS.push({id:shopSlug(finalBundleName),nama:finalBundleName,kategori:"Bundling",harga:38000+(index%7)*6000,rating:4.5+(index%5)/10,ulas:25+(index%8)*15,badge:index%9===0?"Recommended":"",emoji:"🎁",related:plant.id,stok:15+(index%6)*5});
});
SHOP_COMMON_EXTRAS.forEach(([nama,kategori,harga,emoji],index)=>PRODUCTS.push({id:shopSlug(nama),nama,kategori,harga,rating:4.5+(index%5)/10,ulas:65+index*11,badge:index%4===0?"Recommended":"",emoji,related:"",stok:40+index*5}));
PRODUCTS.forEach(product=>{
  const plant=PLANTS.find(item=>item.id===product.related);
  product.isi=product.isi || (product.kategori==="Benih"?"1 sachet benih":product.kategori==="Bibit"?"1 bibit siap tanam":product.kategori==="Bundling"?"1 paket":"1 unit");
  product.manfaat=product.manfaat || (plant?`Mendukung perawatan ${plant.nama}`:"Membantu perawatan kebun sehari-hari");
  product.cocokUntuk=product.cocokUntuk || (plant?plant.nama:"Beragam tanaman");
});

const productIds=PRODUCTS.map(product=>product.id);
const duplicateProductIds=productIds.filter((id,index)=>productIds.indexOf(id)!==index);
if(duplicateProductIds.length){
  throw new Error(`Duplicate product ID: ${duplicateProductIds.join(', ')}`);
}

